INSERT INTO `club_history_milestone` VALUES
(1,1985,'Gründung der VSG \"Fortschritt\" Kugelberg','Gründung am 10.05.1985 in Weißenfels. Die erste Sportstätte war die Turnhalle der 1983 eingeweihten Fritz-Juch-Oberschule, heute Ökowegschule.',1),
(2,1990,'Neugründung als VSG Kugelberg e. V.','Auflösung der VSG \"Fortschritt\" Kugelberg am 13.12.1990 und Neugründung der VSG Kugelberg e. V. am 14.12.1990.',1),
(3,1992,'Anschluss der Tischtennis-Abteilung des 1. SC 1861 Weißenfels','Anschluss am 19.06.1992 mit Sportstätte Albert-Einstein-Oberschule.',1),
(4,2009,'Anschluss der WSG Süd Weißenfels','Anschluss der Volleyball-Abteilung der WSG Süd Weißenfels am 01.11.2009 mit 20 Mitgliedern.',1),
(5,2012,'Anschluss der Badminton-Abteilung von Lok Weißenfels','Anschluss am 01.07.2012 mit 46 Mitgliedern.',1);
INSERT INTO `club_history_special_event` VALUES
(1,'Feier zum 10-jährigen Bestehen im Hotel \"Schöne Aussicht\"','1995-05-20','Festveranstaltung zum 10-jährigen Bestehen mit 110 Teilnehmern und der erstmaligen Ernennung von Ehrenmitgliedern.',1),
(2,'Feier zum 25-jährigen Bestehen in der Gaststätte Bootshaus','2010-05-08','Festveranstaltung zum 25-jährigen Bestehen mit 82 Teilnehmern und erstmaliger Ausgabe von Ehrenbriefen.',1),
(3,'Festumzug zum Sachsen-Anhalt-Tag','2010-08-22','Teilnahme am Festumzug zum Sachsen-Anhalt-Tag in Weißenfels mit 4 Sportfreunden.',1),
(4,'Feier zum 30-jährigen Bestehen in der Gaststätte Bootshaus','2015-05-09','Festveranstaltung zum 30-jährigen Bestehen mit 76 Teilnehmern und der Auszeichnung von Rosa Beck und Hans-Werner Rust mit der Ehrennadel des Landessportbundes in Silber.',1),
(5,'Erste Corona-bedingte Schließung der Sportstätten','2020-03-13','Erstmalige Schließung der vom Verein genutzten Sportstätten aufgrund der Corona-Pandemie; spätere Wiedereröffnungen erfolgten unter Auflagen.',1),
(6,'Wiedereröffnung der Albert-Einstein-Schule','2022-02-01','Wiedereröffnung der Sporthalle der Albert-Einstein-Schule nach über zweijähriger Sanierung.',1),
(7,'Feier zum 40-jährigen Bestehen in der Gaststätte Bootshaus','2025-05-17','Feier zum 40jährigen Bestehen der VSG Kugelberg am 17.05.2025 in der Gaststätte Bootshaus, Auszeichnungen: Ehrenmedaille LSB - Helmut Wiegand, Ehrennadel LSB Gold: Heidrun Hauser, Ehrennadel LSB Silber: Christian Köhler, Ehrennadel LSB Bronze; Mario Fischer und Reinhardt Laue, Ehrentafel VSG Kugelberg: Simone Behm, Andreas Funke, Matthias Fekl, Johannes Fekl, Anita Teichmann,  Claus-Werner Brenner, Bernd Biedermann; Teilnehmer: 63, davon Ehrengäste: Martin Papke (OB Weißenfels), Elke Simon-Kuch (Abgeordnete des Landtages Sachsen-Anhalt), Ulrich Baumann (Vizepräsident des KSB Burgenland)',1);
