INSERT INTO `content_block` VALUES
(1,'h���|A� Jw!*�M','/','Sportverein seit 1985'),
(2,'HV��LjGτ�UINSERT INTO `department` VALUES
(1,'Badminton','badminton','Schnelle Ballwechsel und blitzschnelle Reaktionen! Badminton ist der perfekte Sport, um sich richtig auszupowern. Egal ob im Einzel oder Doppel – hier sind Geschwindigkeit und Taktik gefragt.','purple',1233,6),
(2,'Gymnastik','gymnastik','Fit von Kopf bis Fuß! Mit abwechslungsreichen Übungen kräftigen wir die Muskulatur und halten die Gelenke geschmeidig. Ein effektives Ganzkörpertraining für jede Altersgruppe.','green',1234,4),
(3,'Tischtennis','tischtennis','Reaktionsschnelligkeit und Ballgefühl auf kleinstem Raum. Tischtennis ist das schnellste Rückschlagspiel der Welt und macht einfach riesigen Spaß – egal ob Anfänger oder Fortgeschrittener.','red',1235,9),
(4,'Volleyball','volleyball','Einer für alle, alle für einen! Beim Volleyball stehen Teamgeist und Dynamik im Vordergrund. Pritschen, Baggern und Schmettern – erlebe die Faszination dieses Mannschaftssports.','blue',1236,7);
